            FlPlace(bt, nb, emon.Port.CellsAt(fc, at + 9), emon.Port.CellsAt(fc, at + 1), emon.Port.CellsAt(fc, at + 2), emon.Port.CellsAt(fc, at + 3), emon.Port.CellsAt(fc, at + 4), emon.Port.CellsAt(fc, at + 5), sc);
            emon.Port.CellsSet(fc, at + 6, emon.Port.CellsAt(sc, 0));
            emon.Port.CellsSet(fc, at + 7, emon.Port.CellsAt(sc, 1));
            emon.Port.CellsSet(fc, at + 10, emon.Port.CellsAt(sc, 2));
            // D583: a text field whose label is only found above or nowhere, with a field just to its left on its line that a label to its left was found for, goes with that field (the cents
            // box of a line `dollars . cents` took the line above's label, the nearest above it, and the line below lost it)
            if ((emon.Port.CellsAt(fc, at + 9) >= 4) && (emon.Port.CellsAt(sc, 2) >= 3)) {
                j = FlSibling(fc, i);
                if (j >= 0) {
                    emon.Port.CellsSet(fc, at + 6, emon.Port.CellsAt(fc, (j * FlW) + 6));
                    emon.Port.CellsSet(fc, at + 7, emon.Port.CellsAt(fc, (j * FlW) + 7));
                    emon.Port.CellsSet(fc, at + 10, emon.Port.CellsAt(fc, (j * FlW) + 10));
                }
            }
            i += 1;
        }
        return nf;
    }
    internal static int FlTypeText(emon.Port.Cells text, int kind) {
        // Append the `type` of a field of this `fd-kind` to the text arena: checkbox, radio, text, combo or list.
        if (kind == 2) {
            Model.TextAppendCp(text, 99);
            Model.TextAppendCp(text, 104);
            Model.TextAppendCp(text, 101);
            Model.TextAppendCp(text, 99);
            Model.TextAppendCp(text, 107);
            Model.TextAppendCp(text, 98);
            Model.TextAppendCp(text, 111);
            Model.TextAppendCp(text, 120);
            return 0;
        }
        if (kind == 3) {
            Model.TextAppendCp(text, 114);
            Model.TextAppendCp(text, 97);
            Model.TextAppendCp(text, 100);
            Model.TextAppendCp(text, 105);
            Model.TextAppendCp(text, 111);
            return 0;
        }
        if (kind == 4) {
            Model.TextAppendCp(text, 116);
            Model.TextAppendCp(text, 101);
            Model.TextAppendCp(text, 120);
            Model.TextAppendCp(text, 116);
            return 0;
        }
        if (kind == 5) {
            Model.TextAppendCp(text, 99);
            Model.TextAppendCp(text, 111);
            Model.TextAppendCp(text, 109);
            Model.TextAppendCp(text, 98);
            Model.TextAppendCp(text, 111);
            return 0;
        }
        Model.TextAppendCp(text, 108);
        Model.TextAppendCp(text, 105);
        Model.TextAppendCp(text, 115);
        Model.TextAppendCp(text, 116);
        return 0;
    }
    internal static int FlCopyRun(emon.Port.Cells text, emon.Port.Cells txt, int s, int n) {
        // The run txt[s, s + n) appended to the Model's text arena; answers where it starts there.
        int at = emon.Port.CellsLen(text);
        int i = 0;
        while (i < n) {
            Model.TextAppendCp(text, emon.Port.CellsAt(txt, s + i));
            i += 1;
        }
        return at;
    }
    internal static int FlConf(int fa) {
        // How far a field is trusted, from how /V and the appearance agree (`fa` of `emon.pdfannot`): they agree 950, differ 600, /V alone 850, the appearance
        // alone 700, neither to compare (a field left blank) 900.
        if (fa == 1) {
            return 950;
        }
        if (fa == 2) {
            return 600;
        }
        if (fa == 3) {
            return 850;
        }
        if (fa == 4) {
            return 700;
        }
        return 900;
    }
    internal static int FlField(emon.Port.Cells an, emon.Port.Cells txt, emon.Port.Cells fc, int row, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, int par) {
        // The `field` inline of field row `row` of `fc`, the last child of `par`: its name, type, value (a button's export value) and, of a button, whether it is on.
        int o = row * FlW;
        int at = emon.Port.CellsAt(fc, o) * AnStride;
        int kind = emon.Port.CellsAt(an, at + 8);
        int f = Model.NodeNew(nodes, Model.NkField(), par);
        int s = 0;
        int n = 0;
        int vs = -1;
        int vn = 0;
        if (f < 0) {
            return -1;
        }
        Model.NodeSetSrc(nodes, f, Model.SrAnnot());
        Model.NodeSetConf(nodes, f, FlConf(emon.Port.CellsAt(an, at + 11)));
        n = emon.Port.CellsAt(an, at + 13);
        if ((emon.Port.CellsAt(an, at + 12) >= 0) && (n > 0)) {
            s = FlCopyRun(text, txt, emon.Port.CellsAt(an, at + 12), n);
            Model.NodeSetAttrText(nodes, attrs, f, Model.FkName(), s, n);
        }
        s = emon.Port.CellsLen(text);
        FlTypeText(text, kind);
        Model.NodeSetAttrText(nodes, attrs, f, Model.FkType(), s, emon.Port.CellsLen(text) - s);
        if (kind >= 4) {
            vs = emon.Port.CellsAt(an, at + 14);
            vn = emon.Port.CellsAt(an, at + 15);
        } else {
            vs = emon.Port.CellsAt(an, at + 16);
            vn = emon.Port.CellsAt(an, at + 17);
        }
        if ((vs >= 0) && (vn > 0)) {
            s = FlCopyRun(text, txt, vs, vn);
            Model.NodeSetAttrText(nodes, attrs, f, Model.FkValue(), s, vn);
        }
        if (kind < 4) {
            Model.NodeSetAttrBool(nodes, attrs, f, Model.FkChecked(), emon.Port.CellsAt(an, at + 9));
        }
        Model.NodeAddRegion(nodes, regions, f, emon.Port.CellsAt(fc, o + 1), emon.Port.CellsAt(fc, o + 2), emon.Port.CellsAt(fc, o + 3), emon.Port.CellsAt(fc, o + 4), emon.Port.CellsAt(fc, o + 5));
        return f;
    }
    internal static int FlChain(emon.Port.Cells an, emon.Port.Cells txt, emon.Port.Cells fc, int row0, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, int par) {
        // Every field of the chain that starts at field row `row0`, in order, as the last children of `par`.
        int r = row0;
        while (r >= 0) {
            FlField(an, txt, fc, r, nodes, attrs, regions, text, par);
            r = emon.Port.CellsAt(fc, (r * FlW) + 8);
        }
        return 0;
    }
    internal static int FlOrphans(emon.Port.Cells an, emon.Port.Cells txt, emon.Port.Cells fc, int row0, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, int par) {
        // The fields of the chain that starts at `row0`, which have no label (rule 4): a paragraph of their own under `par` for each page, with the box that holds them.
        int r = row0;
        int p = -1;
        int pg = 0;
        int ux0 = 0;
        int uy0 = 0;
        int ux1 = 0;
        int uy1 = 0;
        int o = 0;
        while (r >= 0) {
            o = r * FlW;
            pg = emon.Port.CellsAt(fc, o + 1);
            p = Model.NodeNew(nodes, Model.NkParagraph(), par);
            if (p < 0) {
                r = -1;
            } else {
                Model.NodeSetText(nodes, p, emon.Port.CellsLen(text), 0);
                Model.NodeSetSrc(nodes, p, Model.SrAnnot());
                Model.NodeAddSrc(nodes, p, Model.SrInfer());
                Model.NodeSetConf(nodes, p, 500);
                ux0 = emon.Port.CellsAt(fc, o + 2);
                uy0 = emon.Port.CellsAt(fc, o + 3);
                ux1 = emon.Port.CellsAt(fc, o + 4);
                uy1 = emon.Port.CellsAt(fc, o + 5);
                while ((r >= 0) && (emon.Port.CellsAt(fc, (r * FlW) + 1) == pg)) {
                    o = r * FlW;
                    FlField(an, txt, fc, r, nodes, attrs, regions, text, p);
                    ux0 = FlMin(ux0, emon.Port.CellsAt(fc, o + 2));
                    uy0 = FlMin(uy0, emon.Port.CellsAt(fc, o + 3));
                    ux1 = FlMax(ux1, emon.Port.CellsAt(fc, o + 4));
                    uy1 = FlMax(uy1, emon.Port.CellsAt(fc, o + 5));
                    r = emon.Port.CellsAt(fc, o + 8);
                }
                Model.NodeAddRegion(nodes, regions, p, pg, ux0, uy0, ux1, uy1);
            }
        }
        return 0;
    }
    internal static int FlHasInline(emon.Port.Cells on, int n) {
        // 1 when node n has an inline child.
        int c = Model.NodeFirstChild(on, n);
        while (c >= 0) {
            if (Model.NodeIsInline(on, c) == 1) {
                return 1;
            }
            c = Model.NodeNext(on, c);
        }
        return 0;
    }
    internal static int FlTree(emon.Port.Cells on, emon.Port.Cells oa, emon.Port.Cells orr, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells nm, emon.Port.Cells an, emon.Port.Cells txt, emon.Port.Cells fc, emon.Port.Cells fh, int n, int np) {
        // Copy old node n and its subtree as the last child of new node np (-1: a new root), with the fields that go in it: those before its text first, then its
        // children (a block that was plain text gets a `text` inline for its words), the fields after its text before its first block child, and the paragraph of the
        // fields that have no label after it (before it, for those placed before) as its siblings; the document's own at its end.
        int hb = emon.Port.CellsAt(fh, n * 4);
        int ha = emon.Port.CellsAt(fh, (n * 4) + 1);
        int ho = emon.Port.CellsAt(fh, (n * 4) + 2);
        int hp = emon.Port.CellsAt(fh, (n * 4) + 3);
        int nn = -1;
        int c = 0;
        int flushed = 0;
        int t = 0;
        if ((hp >= 0) && (np >= 0)) {
            FlOrphans(an, txt, fc, hp, nodes, attrs, regions, text, np);
        }
        nn = Restruct.RsNode(on, oa, orr, nodes, attrs, regions, nm, n, np);
        if (nn < 0) {
            return -1;
        }
        if ((Model.NodeKind(on, n) == Model.NkCell()) && ((hb >= 0) || (ha >= 0))) {
            Model.NodeSetAux(nodes, nn, 0);
        }
        if ((hb >= 0) || (ha >= 0)) {
            FlChain(an, txt, fc, hb, nodes, attrs, regions, text, nn);
            if ((FlHasInline(on, n) == 0) && (Model.NodeHasText(on, n) == 1)) {
                t = Model.NodeNew(nodes, Model.NkText(), nn);
                if (t >= 0) {
                    Model.NodeSetText(nodes, t, Model.NodeTextStart(on, n), Model.NodeTextLen(on, n));
                    Model.NodeSetConf(nodes, t, 1000);
                    Model.NodeAddSrc(nodes, t, Model.SrText());
                }
            }
        }
        c = Model.NodeFirstChild(on, n);
        while (c >= 0) {
            if ((flushed == 0) && (Model.NodeIsInline(on, c) == 0)) {
                FlChain(an, txt, fc, ha, nodes, attrs, regions, text, nn);
                flushed = 1;
            }
            FlTree(on, oa, orr, nodes, attrs, regions, text, nm, an, txt, fc, fh, c, nn);
            c = Model.NodeNext(on, c);
        }
        if (flushed == 0) {
            FlChain(an, txt, fc, ha, nodes, attrs, regions, text, nn);
        }
        if (ho >= 0) {
            if (np >= 0) {
                FlOrphans(an, txt, fc, ho, nodes, attrs, regions, text, np);
            } else {
                FlOrphans(an, txt, fc, ho, nodes, attrs, regions, text, nn);
            }
        }
        return nn;
    }
    public static int FlRun(emon.Port.Cells on, emon.Port.Cells oa, emon.Port.Cells orr, emon.Port.Cells text, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells nm, emon.Port.Cells an, emon.Port.Cells txt, emon.Port.Cells fc, emon.Port.Cells fh, emon.Port.Cells bt, emon.Port.Cells sc) {
        // Copy the old Model's trees into the empty arenas `nodes`, `attrs`, `regions` (the text is shared) with the form fields of `an` put in (see the head).
        // `nm` (old node to new), `fc`, `fh`, `bt` and `sc` are scratch. Answers the new node count, or 0, having written nothing, when `an` has no field.
        if (FlCount(an) == 0) {
            return 0;
        }
        int n = Model.NodeCount(on);
        int ndoc = FlDocEnd(on);
        int nb = FlBlocks(on, orr, text, ndoc, bt);
        int nf = FlCollect(an, bt, nb, fc, sc);
        int i = 0;
        int t = 0;
        int slot = 0;
        int r = 0;
        emon.Port.CellsDrop(fh, 0);
        while (i < (n * 4)) {
            emon.Port.CellsPush(fh, -1);
            i += 1;
        }
        i = nf - 1;
        while (i >= 0) {
            t = emon.Port.CellsAt(fc, (i * FlW) + 6);
            slot = emon.Port.CellsAt(fc, (i * FlW) + 7);
            emon.Port.CellsSet(fc, (i * FlW) + 8, emon.Port.CellsAt(fh, (t * 4) + slot));
            emon.Port.CellsSet(fh, (t * 4) + slot, i);
            i -= 1;
        }
        emon.Port.CellsDrop(nodes, 0);
        emon.Port.CellsDrop(attrs, 0);
        emon.Port.CellsDrop(regions, 0);
        emon.Port.CellsDrop(nm, 0);
        i = 0;
        while (i < n) {
            emon.Port.CellsPush(nm, -1);
            i += 1;
        }
        while (r < n) {
            if (Model.NodeParent(on, r) < 0) {
                FlTree(on, oa, orr, nodes, attrs, regions, text, nm, an, txt, fc, fh, r, -1);
            }
            r += 1;
        }
        Restruct.RsRemap(attrs, nm);
        return Model.NodeCount(nodes);
    }
}
